// What a model costs at its vendor's list price, and what a person sees it
// called, by the name a request gives it, so a graph that meets a model for
// the first time can weigh what it spent and name it. The table is data,
// regenerated by bin/prices.ts from OpenRouter's public listing; a `price` or
// `label` on the model's own row is what a graph uses.

import table from './prices.json' with { type: 'json' }
import type { Price } from './vocab.ts'

let PRICES: Record<string, Price> = table.prices
let LABELS: Record<string, string> = table.labels

// What a name may carry beyond the model's own: a context window in brackets
// (`claude-opus-4-8[1m]`), then a release date (`claude-haiku-4-5-20251001`,
// `gpt-4o-2024-08-06`).
let EXTRA = [/\[[^\]]*\]$/, /-\d{8}$/, /-\d{4}-\d{2}-\d{2}$/]

// The entry `list` holds for the model `name` names, shed of what it carries
// beyond the model's own.
let listed = <T>(list: Record<string, T>, name: string): T | undefined => {
  let at = name
  for (let extra of [/^/, ...EXTRA]) {
    at = at.replace(extra, '')
    if (Object.hasOwn(list, at)) return list[at]
  }
  return undefined
}

/**
 * The list price of the model a request names, if the table holds it.
 *
 * ```ts
 * import { listPrice } from '@yaks/model'
 * import { assertEquals } from '@std/assert'
 *
 * assertEquals(listPrice('claude-haiku-4-5-20251001'), listPrice('claude-haiku-4-5'))
 * assertEquals(listPrice('no-such-model'), undefined)
 * ```
 */
export let listPrice = (name: string): Price | undefined => listed(PRICES, name)

/**
 * What the table calls the model a request names, its window said after it,
 * if the table holds it.
 *
 * ```ts
 * import { listLabel } from '@yaks/model'
 * import { assertEquals } from '@std/assert'
 *
 * assertEquals(listLabel('claude-sonnet-5-5'), 'Sonnet 5.5')
 * assertEquals(listLabel('claude-opus-4-8[1m]'), 'Opus 4.8 1M')
 * assertEquals(listLabel('gpt-6.2-sol'), 'GPT-6.2 Sol')
 * assertEquals(listLabel('no-such-model'), undefined)
 * ```
 */
export let listLabel = (name: string): string | undefined => {
  let label = listed(LABELS, name)
  let window = name.match(/\[([^\]]*)\]$/)?.[1]
  return label && (window ? `${label} ${window.toUpperCase()}` : label)
}
